<script lang="ts">import DashboardContent from '$lib/components/DashboardContent.svelte';import{Button}from'$lib/components/ui/button/index.js';import{Plus}from'lucide-svelte';import{enhance}from'$app/forms';import{dispatchToast}from'$lib/notifications';const{data}= $props();let open=$state(false);const reminders=$derived(data.reminders);function submit(){return async({result,update}:any)=>{if(result.type==='success'){open=false;dispatchToast('Saved',result.data?.message??'Saved')}else if(result.type==='failure')dispatchToast('Error',result.data?.message??'Could not save');await update();}}</script>
<DashboardContent title="Teacher Reminders" subtitle="Operational reminders for lessons, attendance, meetings, ReClass and deadlines">{#snippet headerActions()}<Button size="sm" onclick={()=>open=true}><Plus class="h-3.5 w-3.5"/> Add Reminder</Button>{/snippet}<div class="space-y-3">{#each reminders as r}<div class="flex items-center justify-between rounded-xl border border-border bg-white p-4"><div><p class="text-sm font-semibold">{r.title}</p><p class="text-xs text-muted-foreground">{r.teachers?`${r.teachers.first_name} ${r.teachers.last_name}`:'All teachers'} · {r.reminder_type} · {new Date(r.remind_at).toLocaleString()}</p>{#if r.body}<p class="mt-1 text-xs text-muted-foreground">{r.body}</p>{/if}</div><span class="rounded-full bg-muted px-2 py-1 text-xs capitalize">{r.status}</span></div>{:else}<div class="rounded-xl border border-dashed p-12 text-center text-sm text-muted-foreground">No reminders scheduled.</div>{/each}</div></DashboardContent>
{#if open}<div class="fixed inset-0 z-50 flex items-center justify-center bg-black/30 p-4"><div class="w-full max-w-lg rounded-2xl bg-white shadow-xl"><div class="border-b px-6 py-4"><h2 class="font-semibold">Teacher Reminder</h2></div><form method="POST" action="?/create" use:enhance={submit} class="grid gap-4 px-6 py-5"><label class="text-xs font-medium">Teacher<select name="teacher_id" class="field"><option value="">All teachers</option>{#each data.teachers as t}<option value={t.id}>{t.first_name} {t.last_name}</option>{/each}</select></label><label class="text-xs font-medium">Title<input name="title" required class="field"/></label><label class="text-xs font-medium">Type<select name="reminder_type" class="field"><option value="lesson">Lesson</option><option value="attendance">Attendance</option><option value="meeting">Meeting</option><option value="reclass">ReClass</option><option value="deadline">Deadline</option><option value="announcement">Announcement</option><option value="general">General</option></select></label><label class="text-xs font-medium">Remind At<input name="remind_at" type="datetime-local" required class="field"/></label><label class="text-xs font-medium">Message<textarea name="body" rows="3" class="field"></textarea></label><div class="flex justify-end gap-2"><Button type="button" variant="outline" onclick={()=>open=false}>Cancel</Button><Button type="submit">Schedule</Button></div></form></div></div>{/if}<style>:global(.field){width:100%;margin-top:.3rem;border:1px solid hsl(var(--border));border-radius:.5rem;padding:.55rem .7rem;font-size:.875rem;outline:none}</style>
